texts./api/cluster/secondary-config?primary=19:
// DNSOne secondary: follows the primary's catalog zone, so hosted zones appear and disappear by themselves.
// 1. In the options { } block of named.conf.options, add:
//
//    catalog-zones {
//        zone "catalog.dnsone" default-primaries { 192.0.2.53 port 5301; } zone-directory "/var/cache/bind/catalog";
//    };
//
// 2. Add this to named.conf.local, then: mkdir -p /var/cache/bind/catalog && chown bind: /var/cache/bind/catalog
//    && named-checkconf && rndc reconfig
zone "catalog.dnsone" {
    type secondary;
    primaries { 192.0.2.53 port 5301; };
    file "/var/cache/bind/catalog.dnsone.db";
};
